begin;

alter table public.builders drop constraint if exists builders_jurisdiction_check;
alter table public.builders add constraint builders_jurisdiction_check
  check (jurisdiction in ('ACT', 'NSW', 'NT', 'QLD', 'SA', 'TAS', 'VIC', 'WA'));
alter table public.australian_postcode_centroids drop constraint if exists australian_postcode_centroids_jurisdiction_check;
alter table public.australian_postcode_centroids add constraint australian_postcode_centroids_jurisdiction_check
  check (jurisdiction in ('ACT', 'NSW', 'NT', 'QLD', 'SA', 'TAS', 'VIC', 'WA'));

on conflict (jurisdiction, postcode) do update set
  latitude=excluded.latitude, longitude=excluded.longitude, source=excluded.source;

create temporary table builder_csv_import (
  id uuid not null,
  name text not null,
  slug text not null,
  email text,
  phone text,
  website text,
  description text,
  logo_url text,
  address text,
  suburb text,
  state text not null,
  postcode text,
  latitude numeric,
  longitude numeric,
  service_radius_km numeric,
  verified boolean not null,
  active boolean not null,
  jurisdiction text not null,
  registration_number text,
  registration_status text,
  registry_url text,
  registry_checked_at timestamptz,
  limitations text,
  contact_source text,
  coordinate_source text
) on commit drop;


  id, name, slug, email, phone, website, description, logo_url, address, suburb, state, postcode,
  latitude, longitude, service_radius_km, verified, active, jurisdiction, registration_number,
  registration_status, registry_url, registry_checked_at, limitations, contact_source, coordinate_source
)
select id, name, slug, email, phone, website, description, logo_url, address, suburb, state, postcode,
       latitude, longitude, service_radius_km, verified, active, jurisdiction, registration_number,
       registration_status, registry_url, registry_checked_at, limitations, contact_source, coordinate_source
from (
  select distinct on (jurisdiction, registration_number) *
  from builder_csv_import
  where registration_number is not null
  order by jurisdiction, registration_number, verified desc, (email is not null) desc, (address is not null) desc
) builder_csv_import
on conflict (jurisdiction, registration_number) where registration_number is not null do update set
  email=coalesce(public.builders.email, excluded.email),
  phone=coalesce(public.builders.phone, excluded.phone),
  website=coalesce(public.builders.website, excluded.website),
  description=coalesce(excluded.description, public.builders.description),
  logo_url=coalesce(public.builders.logo_url, excluded.logo_url),
  address=coalesce(excluded.address, public.builders.address),
  suburb=case when excluded.address is not null then coalesce(excluded.suburb, public.builders.suburb) else public.builders.suburb end,
  state=case when excluded.address is not null then coalesce(excluded.state, public.builders.state) else public.builders.state end,
  postcode=case when excluded.address is not null then coalesce(excluded.postcode, public.builders.postcode) else public.builders.postcode end,
  latitude=coalesce(public.builders.latitude, excluded.latitude),
  longitude=coalesce(public.builders.longitude, excluded.longitude),
  verified=public.builders.verified or excluded.verified,
  active=public.builders.active or excluded.active,
  registration_status=case when public.builders.registration_status = 'Current' then public.builders.registration_status else coalesce(excluded.registration_status, public.builders.registration_status) end,
  registry_url=coalesce(public.builders.registry_url, excluded.registry_url),
  registry_checked_at=coalesce(public.builders.registry_checked_at, excluded.registry_checked_at),
  contact_source=coalesce(excluded.contact_source, public.builders.contact_source),
  coordinate_source=coalesce(public.builders.coordinate_source, excluded.coordinate_source),
  updated_at=now();

  id, name, slug, email, phone, website, description, logo_url, address, suburb, state, postcode,
  latitude, longitude, service_radius_km, verified, active, jurisdiction, registration_number,
  registration_status, registry_url, registry_checked_at, limitations, contact_source, coordinate_source
)
select id, name, slug, email, phone, website, description, logo_url, address, suburb, state, postcode,
       latitude, longitude, service_radius_km, verified, active, jurisdiction, null,
       registration_status, registry_url, registry_checked_at, limitations, contact_source, coordinate_source
from builder_csv_import
where registration_number is null
on conflict (slug) do update set
  email=coalesce(public.builders.email, excluded.email),
  phone=coalesce(public.builders.phone, excluded.phone),
  website=coalesce(public.builders.website, excluded.website),
  description=coalesce(excluded.description, public.builders.description),
  address=coalesce(excluded.address, public.builders.address),
  suburb=coalesce(excluded.suburb, public.builders.suburb),
  state=coalesce(excluded.state, public.builders.state),
  postcode=coalesce(excluded.postcode, public.builders.postcode),
  latitude=coalesce(public.builders.latitude, excluded.latitude),
  longitude=coalesce(public.builders.longitude, excluded.longitude),
  verified=public.builders.verified or excluded.verified,
  active=public.builders.active or excluded.active,
  contact_source=coalesce(excluded.contact_source, public.builders.contact_source),
  coordinate_source=coalesce(public.builders.coordinate_source, excluded.coordinate_source),
  updated_at=now();

drop function if exists public.find_matching_builders(text, text, text, numeric, numeric, integer);
create function public.find_matching_builders(
  p_postcode text,
  p_suburb text default null,
  p_state text default null,
  p_latitude numeric default null,
  p_longitude numeric default null,
  p_limit integer default 12
)
returns table (
  builder_id uuid, builder_name text, suburb text, state text, description text,
  logo_url text, registration_number text, distance_km numeric
)
language sql stable security definer set search_path = ''
as $$
  with requested as (
    select upper(trim(coalesce(p_state, ''))) as jurisdiction
  ), target as (
    select r.jurisdiction,
      coalesce(p_latitude, pc.latitude) as latitude,
      coalesce(p_longitude, pc.longitude) as longitude
    from requested r
    left join public.australian_postcode_centroids pc
      on pc.jurisdiction = r.jurisdiction and pc.postcode = trim(p_postcode)
  ), candidates as (
    select b.id, b.name, b.suburb, b.state, b.description, b.logo_url, b.registration_number,
      b.postcode = trim(p_postcode) as same_postcode,
      case when t.latitude is not null and t.longitude is not null and b.latitude is not null and b.longitude is not null
        then round((6371 * acos(least(1, greatest(-1,
          cos(radians(t.latitude)) * cos(radians(b.latitude)) *
          cos(radians(b.longitude) - radians(t.longitude)) +
          sin(radians(t.latitude)) * sin(radians(b.latitude))
        ))))::numeric, 1)
        else null end as calculated_distance
    from public.builders b cross join target t
    where b.active and b.verified and b.jurisdiction = t.jurisdiction
  )
  select c.id, c.name, c.suburb, c.state, c.description, c.logo_url, c.registration_number, c.calculated_distance
  from candidates c
  order by c.calculated_distance nulls last, c.same_postcode desc, c.name
  limit least(greatest(coalesce(p_limit, 12), 1), 30);
$$;
revoke all on function public.find_matching_builders(text, text, text, numeric, numeric, integer) from public;
grant execute on function public.find_matching_builders(text, text, text, numeric, numeric, integer) to anon, authenticated;

commit;
